<script setup>
import { onMounted, reactive, ref } from 'vue'
import FloatingWindow from '../components/common/FloatingWindow.vue'
import NeonPanel from '../components/common/NeonPanel.vue'
import { useAppStore } from '../stores/app'
const store = useAppStore(); const editor = ref(false); const policy = reactive({ retentionDays: 30, allowUpload: false, allowDownload: false, allowClipboard: true, recordSessions: true, brokerSshUrl: '', brokerRdpUrl: '' })
async function load() { Object.assign(policy, await store.remoteSessionSettings()) }
async function save() { Object.assign(policy, await store.saveRemoteSessionSettings(policy)); editor.value = false }
onMounted(load)
</script>
<template><div class="remote-session-workspace"><div class="toolbar-row"><div><p class="section-eyebrow">Governed Interactive Access</p><h2 class="page-title">Remote Session Control</h2></div><v-btn class="glass-button" prepend-icon="mdi-shield-cog-outline" @click="editor = true">Configure Policy</v-btn></div><NeonPanel subtitle="Session Safety" title="Remote Access Guardrails"><div class="guardrail-grid"><article><v-icon icon="mdi-text-box-check-outline" color="success"/><strong>{{ policy.recordSessions ? 'Transcript recording enabled' : 'Transcript recording disabled' }}</strong><span>{{ policy.retentionDays }} day retention · redacted command/output ledger</span></article><article><v-icon :icon="policy.allowClipboard ? 'mdi-content-paste' : 'mdi-content-paste-off'" :color="policy.allowClipboard ? 'info' : 'warning'"/><strong>Clipboard {{ policy.allowClipboard ? 'allowed and audited' : 'blocked' }}</strong><span>Only clipboard event metadata and length are retained.</span></article><article><v-icon :icon="policy.allowUpload || policy.allowDownload ? 'mdi-folder-transfer-outline' : 'mdi-folder-lock-outline'" color="warning"/><strong>Transfer guard: {{ policy.allowUpload || policy.allowDownload ? 'policy enabled' : 'deny by default' }}</strong><span>Allowed transfers still require a brokered provider; no direct transfer is performed.</span></article><article><v-icon icon="mdi-connection" color="secondary"/><strong>Broker integrations</strong><span>{{ policy.brokerSshUrl ? 'SSH configured' : 'SSH not configured' }} · {{ policy.brokerRdpUrl ? 'RDP configured' : 'RDP not configured' }}</span></article></div></NeonPanel><FloatingWindow v-model="editor" title="Remote Session Policy" :width="620" :start-x="345" :start-y="105"><form class="policy-form" @submit.prevent="save"><v-text-field v-model.number="policy.retentionDays" type="number" min="1" max="3650" label="Transcript retention (days)"/><v-switch v-model="policy.recordSessions" color="success" density="compact" label="Record redacted terminal transcripts"/><v-switch v-model="policy.allowClipboard" color="secondary" density="compact" label="Allow and audit clipboard operations"/><v-switch v-model="policy.allowUpload" color="warning" density="compact" label="Permit upload guard (broker required)"/><v-switch v-model="policy.allowDownload" color="warning" density="compact" label="Permit download guard (broker required)"/><v-text-field v-model="policy.brokerSshUrl" label="Brokered SSH URL template" hint="Use {{target}} and {{machineId}} placeholders." persistent-hint/><v-text-field v-model="policy.brokerRdpUrl" label="Brokered RDP URL template" hint="Use {{target}} and {{machineId}} placeholders." persistent-hint/><v-alert type="info" density="compact" variant="tonal">Broker launch URLs contain only target identity. POSHinit never embeds credentials in a broker URL.</v-alert><div class="actions"><v-btn variant="text" @click="editor = false">Cancel</v-btn><v-btn class="glass-button" type="submit">Save Policy</v-btn></div></form></FloatingWindow></div></template>
<style scoped>.remote-session-workspace,.guardrail-grid,.policy-form{display:grid;gap:14px}.guardrail-grid{grid-template-columns:repeat(auto-fit,minmax(230px,1fr));padding:14px}.guardrail-grid article{display:grid;gap:8px;padding:14px;border:1px solid var(--line);background:linear-gradient(135deg,rgba(40,211,255,.06),rgba(190,77,255,.05))}.guardrail-grid strong{font-size:.82rem}.guardrail-grid span{color:var(--muted);font-size:.73rem}.actions{display:flex;justify-content:flex-end;gap:8px}</style>
